import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

// Story 14-S3 — New-puzzle dialog, checked in the source.
//
// The dialog paints only through the redesign's tokens, labels its field
// "Name it!" with a matching accessible name, and names its size group by
// the visible heading. The name generator is the app's own code, with no
// imports and no word-list dependency. The rendered dialog is checked in the
// browser by e2e/new-puzzle-dialog.spec.ts.
// Do not edit this file to match an implementation.

const ROOT = fileURLToPath(new URL('../../../', import.meta.url));

function source(path: string) {
  return readFileSync(join(ROOT, path), 'utf8');
}

function withoutComments(code: string) {
  return code.replace(/\/\*[\s\S]*?\*\//g, '').replace(/(^|[^:])\/\/.*$/gm, '$1');
}

const OLD_COLOR_TOKENS = [
  'background',
  'foreground',
  'ink-2',
  'ink-3',
  'rule',
  'rule-strong',
  'hover-tint',
  'panel-tint',
  'accent',
  'accent-hover',
  'ok-tint',
  'required',
  'recommended',
  'incomplete',
];

function expectRedesignTokensOnly(code: string, label: string) {
  expect(code, label).not.toMatch(/#[0-9a-f]{3,8}\b/i);
  expect(code, label).not.toMatch(/\b(rgb|rgba|hsl|hsla|oklch)\(/);
  expect(code, label).not.toMatch(/\b(text|bg|border|fill|stroke)-(white|black)\b/);
  expect(code, label).not.toMatch(/\bring-/);
  expect(code, label).not.toMatch(/\brounded-(btn|sm|md|lg|grid)\b/);
  expect(code, label).not.toMatch(/\bshadow\b|\bshadow-/);
  expect(code, label).not.toMatch(/\bfont-display\b|\btext-(headline|body|help|xl|title)(?![\w-])/);
  expect(code, label).not.toMatch(/\btext-(xs|sm|base|lg|[2-9]xl)\b/);
  expect(code, label).not.toMatch(/\[font-weight:/);
  for (const name of OLD_COLOR_TOKENS) {
    expect(code, `${label}: ${name}`).not.toMatch(
      new RegExp(`(?:^|[\\s'"\`:])(?:text|bg|border|fill|stroke)-${name}(?![\\w-])`),
    );
  }
}

describe('14-S3 new-puzzle dialog source', () => {
  const dialog = withoutComments(source('src/components/puzzle/NewPuzzleDialog.tsx'));

  it('uses only the redesign tokens', () => {
    expectRedesignTokensOnly(dialog, 'NewPuzzleDialog.tsx');
  });

  it('labels the field "Name it!" with a matching accessible name, and names the size group by its heading', () => {
    const inputs = dialog.match(/<TextInput\b[\s\S]*?\/>/g) ?? [];
    expect(inputs).toHaveLength(1);
    expect(inputs[0]).toMatch(/\blabel="Name it!"/);
    expect(inputs[0]).toMatch(/\baria-label="Name it!"/);
    expect(inputs[0]).toMatch(/\bplaceholder="Add name here\.\.\."/);

    const groups = dialog.match(/<RadioGroup\b[\s\S]*?\/>/g) ?? [];
    expect(groups).toHaveLength(1);
    expect(groups[0]).toMatch(/\blabelledBy=/);
    expect(groups[0]).not.toMatch(/\blabel=/);
    expect(dialog).toContain('And pick a size!');
    expect(dialog).toContain('title="A New Puzzle!"');
  });

  it('generates names with its own code: no imports and no word-list package', () => {
    const generator = withoutComments(source('src/lib/puzzle-name.ts'));
    expect(generator).not.toMatch(/^\s*import\b/m);
    expect(generator).not.toMatch(/\brequire\(/);
    const pkg = JSON.parse(source('package.json')) as Record<string, Record<string, string> | undefined>;
    const deps = { ...pkg.dependencies, ...pkg.devDependencies };
    for (const name of ['unique-names-generator', 'random-word-slugs']) {
      expect(Object.keys(deps), name).not.toContain(name);
    }
  });
});
